// Generic fallback portals — used when the vendor isn't in our curated
// login-info list but we still want to send the user to *some* official
// vendor surface. These deep-link to the vendor's home / search page; the
// switch's model is appended where it makes sense.
export const VENDOR_FALLBACK = {
  cisco:     'https://www.cisco.com/c/en/us/support/index.html',
  juniper:   'https://www.juniper.net/support/',
  arista:    'https://www.arista.com/en/support/',
  hpe:       'https://support.hpe.com/connect/s/',
  aruba:     'https://support.hpe.com/connect/s/',
  dell:      'https://www.dell.com/support/home/en-in',
  fortinet:  'https://support.fortinet.com/',
  extreme:   'https://www.extremenetworks.com/support',
  netgear:   'https://www.netgear.com/support/',
  tplink:    'https://www.tp-link.com/support/',
  dlink:     'https://www.dlink.com/support/',
  ubiquiti:  'https://help.ui.com/',
  mikrotik:  'https://mikrotik.com/support',
};

// Aliases — map common short names to their canonical entry.
export const VENDOR_ALIAS = {
  'mikrotik': 'mikrotik',
  'cisco': 'cisco',
  'hp': 'hpearubanetworking',
  'hpe': 'hpearubanetworking',
  'aruba': 'hpearubanetworking',
  'arista': 'aristanetworks',
  'juniper': 'junipernetworks',
  'extreme': 'extremenetworks',
  'tplink': 'tplink',
  'tp-link': 'tplink',
  'd-link': 'dlink',
  'dell': 'delltechnologies',
  'fortinet': 'fortinet',
  'ruijie': 'ruijienetworks',
  'huawei': 'huawei',
  'zyxel': 'zyxel',
  'netgear': 'netgear',
  'ubiquiti': 'ubiquiti',
  'planet': 'planettechnology',
  'allied': 'alliedtelesis',
  'moxa': 'moxa',
  'h3c': 'h3c',
  'belden': 'belden',
  'hirschmann': 'hirschmann',
  'nvidia': 'nvidia',
  'fs': 'fscom',
};

// Normalize a vendor string to the same key shape used in VENDOR_LOGIN:
// lowercase, alphanumerics only.
function normalize(name) {
  if (!name) return '';
  return String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
}

/**
 * Look up a login portal for a given vendor name.
 * Returns { name, url, source } where source is:
 *   - 'login'    → curated per-vendor login portal from login-info.xlsx
 *   - 'fallback' → generic vendor support/site landing page
 *   - null       → nothing found
 *
 * Matching strategy:
 *   1. Exact normalized match against VENDOR_LOGIN keys.
 *   2. VENDOR_ALIAS short-name → canonical key.
 *   3. Substring match: any VENDOR_LOGIN key fully contained in / containing
 *      the normalized vendor (handles "Cisco Systems" → "cisco", etc.).
 *   4. VENDOR_FALLBACK by alias key.
 */
export function findVendorLogin(vendor) {
  const key = normalize(vendor);
  if (!key) return null;

  if (VENDOR_LOGIN[key]) {
    return { ...VENDOR_LOGIN[key], source: 'login' };
  }
  if (VENDOR_ALIAS[key] && VENDOR_LOGIN[VENDOR_ALIAS[key]]) {
    return { ...VENDOR_LOGIN[VENDOR_ALIAS[key]], source: 'login' };
  }
  // Substring scan — pick the longest matching key so e.g. "alliedtelesis"
  // wins over "allied" when both could match.
  let best = null;
  for (const k of Object.keys(VENDOR_LOGIN)) {
    if (key.includes(k) || k.includes(key)) {
      if (!best || k.length > best.length) best = k;
    }
  }
  if (best) return { ...VENDOR_LOGIN[best], source: 'login' };

  // Fallback portal by alias key.
  for (const [alias, url] of Object.entries(VENDOR_FALLBACK)) {
    if (key.includes(alias) || alias.includes(key)) {
      return { name: vendor, url, source: 'fallback' };
    }
  }
  return null;
}

